// bureau.ts — minimal client for scripts (Node 18+ or Bun).
const base = process.env.BUREAU_URL!;
const token = process.env.BUREAU_TOKEN!;

async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(`${base}${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json", ...init.headers },
  });
  const body = await res.json();
  if (!res.ok) throw new Error(`${res.status} ${body.error ?? res.statusText}`);
  return body as T;
}

type Entry = { direction: "from_agent" | "to_agent"; senderAgentId?: string; text: string };
type Drain = { entries: Entry[]; latestSequence: number };

const drain = (after: number) => api<Drain>("/api/me/api-token-inbox/drain", { method: "POST", body: JSON.stringify({ after }) });

export async function ask(agentId: string, text: string, timeoutMs = 600_000): Promise<string> {
  let after = (await drain(0)).latestSequence;
  await api(`/api/agents/${agentId}/messages`, {
    method: "POST",
    headers: { "Idempotency-Key": crypto.randomUUID() },
    body: JSON.stringify({ text }),
  });
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const inbox = await drain(after);
    const reply = inbox.entries.find((e) => e.direction === "from_agent" && e.senderAgentId === agentId);
    if (reply) return reply.text;
    after = inbox.latestSequence;
    await new Promise((resolve) => setTimeout(resolve, 5_000));
  }
  throw new Error("Timed out waiting for a reply");
}

import { ask } from "./bureau.ts";

const answer = await ask(process.env.AGENT_ID!, "Review the open PRs and list blockers.");
console.log(answer);
